public static String generateStatement(Invoice invoice, Map<String, Play> plays) {
        StringBuilder result = new StringBuilder("Statement for " + invoice.getCustomer() + "\n");

        double totalAmount = 0;
        int volumeCredits = 0;

        for (Performance performance : invoice.getPerformances()) {
            Play play = plays.get(performance.getPlayID());
            double thisAmount = calculateAmount(play, performance);

            volumeCredits += calculateVolumeCredits(play, performance);

            result.append(String.format(" %s: %s (%d seats)\n",
                    play.getName(), NumberFormat.getCurrencyInstance(Locale.US).format(thisAmount / 100),
                    performance.getAudience()));
            totalAmount += thisAmount;
        }

        result.append(String.format("Amount owed is %s\n",
                NumberFormat.getCurrencyInstance(Locale.US).format(totalAmount / 100)));
        result.append(String.format("You earned %d credits\n", volumeCredits));

        return result.toString();
    }

    private static double calculateAmount(Play play, Performance performance) {
        double amount = 0;
        switch (play.getType()) {
            case "tragedy":
                amount = 40000;
                if (performance.getAudience() > 30) {
                    amount += 1000 * (performance.getAudience() - 30);
                }
                break;

            case "comedy":
                amount = 30000;
                if (performance.getAudience() > 20) {
                    amount += 10000 + 500 * (performance.getAudience() - 20);
                }
                amount += 300 * performance.getAudience();
                break;

            default:
                throw new IllegalArgumentException("Unknown type: " + play.getType());
        }
        return amount;
    }

    private static int calculateVolumeCredits(Play play, Performance performance) {
        int credits = 0;
        credits += Math.max(performance.getAudience() - 30, 0);
        if ("comedy".equals(play.getType())) {
            credits += Math.floor(performance.getAudience() / 5);
        }
        return credits;
    }
